// MARK: - algorithm: algorithm_checked_arith

@Test func algorithmCheckedArithMatchesReference() throws {

    for testCase in try oracleCases("pure_functions", "algorithm_checked_arith") {
        let args = try oracleArray(testCase.member("args"))
        let arg0 = try oracleInteger(args[0], as: Int32.self)
        let arg1 = try oracleInteger(args[1], as: Int32.self)
        let arg2 = try oracleInteger(args[2], as: UInt8.self)
        let outcome = Result { try AlgorithmCheckedArith.algorithmCheckedArith(arg0, arg1, arg2) }
        if case .text(let fails)? = testCase.member("fails") {
            switch outcome {
            case .failure(let error as AlgorithmError):
                #expect(error.contractName == fails, "algorithm_checked_arith")
            case .failure(let error):
                Issue.record("algorithm_checked_arith: the case expects the failure \(fails), got \(error)")
            case .success(let value):
                Issue.record("algorithm_checked_arith: the case expects a failure, got \(value)")
            }
            continue
        }
        guard case .success(let returned) = outcome else {
            Issue.record("algorithm_checked_arith: the case expects a value, got \(outcome)")
            continue
        }
        let expected = try oracleInteger(testCase.member("expected"), as: Int32.self)
        #expect(returned == expected, "algorithm_checked_arith")
    }}

